class Solution {public:vector<vector<string>> solve(vector<string> words){map<string,vector<string>> groups;for(string w:words){string key=w;sort(key.begin(),key.end());groups[key].push_back(w);}vector<vector<string>> result;for(auto &entry:groups){sort(entry.second.begin(),entry.second.end());result.push_back(entry.second);}sort(result.begin(),result.end(),[](auto&a,auto&b){return a[0]<b[0];});return result;}};